<?php
require_once dirname(__DIR__,2).'/app/views.php'; $u=require_role(['staff','admin']); $error=null;
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); try { $id=integer_input('id',1,PHP_INT_MAX); $response=text_input('response',3,5000); if (!sql('SELECT id FROM queries WHERE id=?',[$id])->fetchColumn()) throw new InvalidArgumentException('Enquiry not found.'); sql('UPDATE queries SET response=?,responded_by=?,responded_at=CURRENT_TIMESTAMP WHERE id=?',[$response,$u['id'],$id]); flash('Reply saved. The traveller can read it in their account.'); go('/staff/queries.php'); } catch (InvalidArgumentException $ex) {$error=$ex->getMessage();} }
$queries=sql('SELECT q.*,u.name,u.email FROM queries q JOIN users u ON u.id=q.user_id ORDER BY (q.response IS NULL) DESC,q.id DESC')->fetchAll(); page_start('Customer enquiries'); heading('STAFF WORKSPACE','A little help goes a long way.'); ?>
<section class="container pb-5"><?php dashboard_nav('Enquiries'); error_box($error); ?><?php if (!$queries): ?><div class="empty-state"><h2>All quiet for now.</h2><p>Customer enquiries will appear here.</p></div><?php endif; ?><div class="row g-4"><?php foreach ($queries as $q): ?><div class="col-lg-6"><article class="surface h-100"><div class="d-flex justify-content-between gap-3"><h2 class="h4"><?= e($q['subject']) ?></h2><?= status_badge($q['response']?'answered':'pending') ?></div><p class="small muted"><?= e($q['name']) ?> · <?= e($q['email']) ?><br><?= e($q['created_at']) ?></p><p class="preserve-lines"><?= e($q['message']) ?></p><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$q['id'] ?>"><label class="form-label" for="reply-<?= (int)$q['id'] ?>">Your reply</label><textarea class="form-control mb-3" id="reply-<?= (int)$q['id'] ?>" name="response" rows="4" required minlength="3" maxlength="5000"><?= e($q['response']??'') ?></textarea><button class="btn btn-primary">Save reply</button></form></article></div><?php endforeach; ?></div></section>
<?php page_end(); ?>
